//! Related-scope analysis, obligations, reviews, typed messages, replay and waits (#21).
//! Analyzer checks use the real pinned rust-analyzer/Cargo and gopls/Go toolchains.
mod support;

use falinks::*;
use std::{collections::BTreeMap, path::Path, time::Duration};
use support::{GO, PAIR, edit, fixture, go_toolchain, open, pin, reopen};

const RUST: &[(&str, &str)] = &[
    (
        "Cargo.toml",
        "[package]\nname = \"probe\"\nversion = \"0.1.0\"\nedition = \"2024\"\n",
    ),
    (
        "Cargo.lock",
        "# This file is automatically @generated by Cargo.\n# It is not intended for manual editing.\nversion = 4\n\n[[package]]\nname = \"probe\"\nversion = \"0.1.0\"\n",
    ),
    (
        "src/lib.rs",
        "mod dep;\n\npub fn left() -> i32 {\n    1\n}\n\npub fn right() -> i32 {\n    dep::callee()\n}\n",
    ),
    ("src/dep.rs", "pub fn callee() -> i32 {\n    7\n}\n"),
];

fn rust_toolchain() -> Toolchain {
    let bin = Path::new(env!("CARGO")).parent().unwrap();
    Toolchain {
        language: Language::Rust,
        executables: ["rust-analyzer", "cargo", "rustc"]
            .iter()
            .map(|t| pin(bin.join(t)))
            .collect(),
        features: Vec::new(),
    }
}
fn text(capture: &Capture, path: &str) -> String {
    String::from_utf8(capture.files[path].file.as_ref().unwrap().bytes.clone()).unwrap()
}

#[test]
fn rust_and_go_evidence_identify_owners_and_compiler_relationships() {
    for (files, toolchain, right, callee) in [
        (
            RUST,
            rust_toolchain(),
            "src/lib.rs#right",
            "src/dep.rs#callee",
        ),
        (GO, go_toolchain(), "siblings.go#Right", "callee.go#Callee"),
    ] {
        let (_dir, engine, _, _) = fixture(files);
        let evidence = engine.configure_analysis(vec![toolchain.clone()]).unwrap();
        let evidence = &evidence[0];
        assert!(evidence.errors.is_empty(), "{:?}", evidence.errors);
        assert!(evidence.unknown.is_empty(), "{:?}", evidence.unknown);
        assert_eq!(evidence.tree, engine.capture().unwrap().tree);
        assert_eq!(evidence.tools.len(), toolchain.executables.len());
        assert!(evidence.tools.iter().all(|t| !t.version.is_empty()));
        let owners: Vec<_> = evidence.owners.values().flatten().map(|o| &o.id).collect();
        assert!(owners.iter().any(|o| *o == right), "{owners:?}");
        assert!(owners.iter().any(|o| *o == callee), "{owners:?}");
        assert!(
            evidence
                .edges
                .contains(&(right.to_string(), callee.to_string())),
            "{:?}",
            evidence.edges
        );
    }
}

fn scope(id: &str, nodes: &[&str]) -> Scope {
    Scope {
        id: id.into(),
        task: format!("task {id}"),
        nodes: nodes.iter().map(|n| n.to_string()).collect(),
        depends: Default::default(),
    }
}
fn keep(scope: &str, revision: u64) -> Review {
    Review {
        scope: scope.into(),
        revision,
        decision: Decision::Keep,
        note: "reread current owners".into(),
    }
}
fn reread(engine: &Engine, client: &Client, scope: &str) -> Obligation {
    let capture = engine.capture_for(client).unwrap();
    engine
        .review(client, keep(scope, capture.revision))
        .unwrap()
}
fn pending(engine: &Engine, client: &Client) -> Vec<String> {
    engine
        .obligations(client)
        .unwrap()
        .into_iter()
        .filter(Obligation::pending)
        .map(|o| o.scope.id)
        .collect()
}

#[test]
fn rust_relationships_notify_related_scopes_and_let_unrelated_work_proceed() {
    let (_dir, engine, alice, bob) = fixture(RUST);
    engine.configure_analysis(vec![rust_toolchain()]).unwrap();
    engine
        .register(&alice, scope("right", &["src/lib.rs#right"]))
        .unwrap();
    // A sibling owner is model-proven unrelated: no obligation.
    let base = engine.capture().unwrap();
    let left = text(&base, "src/lib.rs").replace("    1\n", "    // grown\n    2\n");
    assert!(matches!(
        engine
            .apply(&bob, edit("left", &base, "src/lib.rs", &left))
            .unwrap(),
        Outcome::Applied { .. }
    ));
    assert!(pending(&engine, &alice).is_empty());
    // Evidence is bound to exact bytes: a shifted owner gets fresh ranges, never old ones.
    let span = |capture: &Capture| {
        let evidence = engine.evidence(capture).unwrap().remove(0);
        assert_eq!(evidence.tree, capture.tree);
        let owner = evidence.owners["src/lib.rs"]
            .iter()
            .find(|o| o.id == "src/lib.rs#right");
        owner.map(|o| o.start).unwrap()
    };
    let grown = "    // grown\n".len();
    assert_eq!(span(&base) + grown, span(&engine.capture().unwrap()));
    // The callee `right` uses is related: a durable obligation.
    let current = engine.capture().unwrap();
    let callee = "pub fn callee() -> i32 {\n    8\n}\n";
    engine
        .apply(&bob, edit("callee", &current, "src/dep.rs", callee))
        .unwrap();
    assert_eq!(pending(&engine, &alice), ["right"]);
    // Related writes are gated; unrelated owners in the same file still progress.
    let current = engine.capture().unwrap();
    let related = text(&current, "src/lib.rs").replace("dep::callee()", "dep::callee() + 1");
    assert!(matches!(
        engine
            .apply(&alice, edit("related", &current, "src/lib.rs", &related))
            .unwrap(),
        Outcome::Unreviewed { .. }
    ));
    let unrelated = text(&current, "src/lib.rs").replace("    2\n", "    3\n");
    assert!(matches!(
        engine
            .apply(
                &alice,
                edit("unrelated", &current, "src/lib.rs", &unrelated)
            )
            .unwrap(),
        Outcome::Applied { .. }
    ));
    assert_eq!(pending(&engine, &alice), ["right"]);
    // Distinct symbols never weaken file freshness.
    let stale = text(&current, "src/lib.rs").replace("    2\n", "    4\n");
    assert!(matches!(
        engine
            .apply(&bob, edit("stale-left", &current, "src/lib.rs", &stale))
            .unwrap(),
        Outcome::Stale { .. }
    ));
    // An earlier review cannot cover a later change, even one restoring old bytes.
    let reviewed_before = engine.capture_for(&alice).unwrap();
    let restore = "pub fn callee() -> i32 {\n    7\n}\n";
    engine
        .apply(
            &bob,
            edit("restore", &reviewed_before, "src/dep.rs", restore),
        )
        .unwrap();
    let partial = engine
        .review(
            &alice,
            Review {
                scope: "right".into(),
                revision: reviewed_before.revision,
                decision: Decision::Revise,
                note: "reviewed the older revision".into(),
            },
        )
        .unwrap();
    assert!(partial.pending());
    assert!(!reread(&engine, &alice, "right").pending());
    let current = engine.capture().unwrap();
    let related = text(&current, "src/lib.rs").replace("dep::callee()", "dep::callee() + 1");
    assert!(matches!(
        engine
            .apply(
                &alice,
                edit("related-after-review", &current, "src/lib.rs", &related)
            )
            .unwrap(),
        Outcome::Applied { .. }
    ));
    let live_edits: Vec<_> = engine
        .events(&bob, 0)
        .unwrap()
        .into_iter()
        .filter_map(|e| match e.body {
            Body::Message(m) if m.kind == Kind::LiveEdit => Some(m),
            _ => None,
        })
        .collect();
    let last = live_edits.last().unwrap();
    assert_eq!(last.sender, 0);
    assert_eq!(last.work, Work::Revision(current.revision + 1));
    assert_eq!(last.scope, ["src/lib.rs#right"]);
}

#[test]
fn broken_go_evidence_and_configuration_changes_widen_symmetrically() {
    let (_dir, engine, alice, bob) = fixture(GO);
    engine.configure_analysis(vec![go_toolchain()]).unwrap();
    engine
        .register(&alice, scope("left", &["siblings.go#Left"]))
        .unwrap();
    let callee =
        |body: &str| format!("package probe\n\nfunc Callee() int {{\n\treturn {body}\n}}\n");
    let base = engine.capture().unwrap();
    engine
        .apply(&bob, edit("healthy", &base, "callee.go", &callee("8")))
        .unwrap();
    assert!(
        pending(&engine, &alice).is_empty(),
        "Callee is unrelated to Left"
    );
    let current = engine.capture().unwrap();
    engine
        .apply(
            &bob,
            edit("broken", &current, "callee.go", &callee("Undefined()")),
        )
        .unwrap();
    let evidence = engine.evidence(&engine.capture().unwrap()).unwrap();
    assert!(evidence[0].units.values().any(|u| !u.broken.is_empty()));
    assert_eq!(pending(&engine, &alice), ["left"], "broken package widens");
    reread(&engine, &alice, "left");
    let current = engine.capture().unwrap();
    engine
        .apply(
            &bob,
            edit(
                "config",
                &current,
                "go.mod",
                "module example.com/probe\n\ngo 1.23\n",
            ),
        )
        .unwrap();
    assert_eq!(
        pending(&engine, &alice),
        ["left"],
        "configuration widens to everything"
    );
}

#[test]
fn interface_implementations_relate_without_any_reference_edge() {
    let (_dir, engine, alice, bob) = fixture(&[
        ("go.mod", "module example.com/probe\n\ngo 1.22\n"),
        (
            "shape.go",
            "package probe\n\ntype Shape interface {\n\tArea() int\n}\n",
        ),
        (
            "square.go",
            "package probe\n\ntype Square struct{}\n\nfunc (Square) Area() int {\n\treturn 1\n}\n",
        ),
    ]);
    engine.configure_analysis(vec![go_toolchain()]).unwrap();
    engine
        .register(&alice, scope("shape", &["shape.go#Shape"]))
        .unwrap();
    let base = engine.capture().unwrap();
    let square = text(&base, "square.go").replace("return 1", "return 2");
    engine
        .apply(&bob, edit("area", &base, "square.go", &square))
        .unwrap();
    assert_eq!(pending(&engine, &alice), ["shape"]);
}

#[test]
fn changed_pins_and_unknown_input_universes_fail_closed() {
    let (_dir, engine, alice, bob) = fixture(RUST);
    let mut wrong = rust_toolchain();
    wrong.executables[0].sha256 = "0".repeat(64);
    assert!(engine.configure_analysis(vec![wrong]).is_err());
    // Without verified evidence every change is related.
    engine
        .register(&alice, scope("right", &["src/lib.rs#right"]))
        .unwrap();
    let base = engine.capture().unwrap();
    let left = text(&base, "src/lib.rs").replace("    1\n", "    2\n");
    engine
        .apply(&bob, edit("left", &base, "src/lib.rs", &left))
        .unwrap();
    assert_eq!(pending(&engine, &alice), ["right"]);

    let mut files = RUST.to_vec();
    files[0].1 = "[package]\nname = \"probe\"\nversion = \"0.1.0\"\nedition = \"2024\"\nbuild = \"build.rs\"\n";
    files.push(("build.rs", "fn main() {}\n"));
    let (_dir, engine, alice, _) = fixture(&files);
    let evidence = engine.configure_analysis(vec![rust_toolchain()]).unwrap();
    assert!(!evidence[0].unknown.is_empty());
    let base = engine.capture().unwrap();
    let left = text(&base, "src/lib.rs").replace("    1\n", "    2\n");
    assert!(matches!(
        engine.apply(&alice, edit("blocked", &base, "src/lib.rs", &left)).unwrap(),
        Outcome::Rejected { reason } if reason.contains("recapture")
    ));
    assert_eq!(engine.capture().unwrap(), base);
}

#[test]
fn deferred_relevant_edit_blocks_stale_and_unreviewed_writes_until_reassessment() {
    let (_dir, engine, alice, bob) = fixture(PAIR);
    engine.register(&alice, scope("a", &["a.rs"])).unwrap();
    let base = engine.capture().unwrap();
    engine
        .apply(&bob, edit("peer", &base, "b.rs", "fn b() { a(); }\n"))
        .unwrap();
    let events = engine.events(&alice, 0).unwrap();
    assert_eq!(events.len(), 2, "{events:?}");
    let deferred = events
        .iter()
        .map(|e| (e.seq, "finish reasoning".to_string()))
        .collect();
    engine
        .handle(&alice, Some(events[1].seq), &deferred, &[])
        .unwrap();
    // Deferral and receipt are not reassessment.
    assert_eq!(pending(&engine, &alice), ["a"]);
    // Alice's write relies on b.rs as she last read it.
    let mut stale = edit("stale", &base, "a.rs", "fn a() { old }\n");
    stale
        .expected
        .insert("b.rs".into(), base.files["b.rs"].version);
    assert!(matches!(
        engine.apply(&alice, stale).unwrap(),
        Outcome::Stale { .. }
    ));
    let current = engine.capture().unwrap();
    assert!(matches!(
        engine
            .apply(
                &alice,
                edit("unreviewed", &current, "a.rs", "fn a() { new }\n")
            )
            .unwrap(),
        Outcome::Unreviewed { .. }
    ));
    engine
        .handle(&alice, None, &BTreeMap::new(), &seqs(&events))
        .unwrap();
    assert!(engine.pending(&alice).unwrap().deferred.is_empty());
    assert_eq!(pending(&engine, &alice), ["a"]);
    reread(&engine, &alice, "a");
    assert!(matches!(
        engine
            .apply(
                &alice,
                edit("reviewed", &current, "a.rs", "fn a() { new }\n")
            )
            .unwrap(),
        Outcome::Applied { .. }
    ));
    assert!(engine.request(&alice, "unreviewed").unwrap().is_some());
}

#[test]
fn a_review_names_only_a_revision_captured_for_the_reviewer() {
    let (_dir, engine, alice, bob) = fixture(PAIR);
    engine.register(&alice, scope("a", &["a.rs"])).unwrap();
    engine.register(&bob, scope("b", &["b.rs"])).unwrap();
    let base = engine.capture_for(&alice).unwrap();
    engine
        .apply(&alice, edit("peer", &base, "a.rs", "fn a() { 2 }\n"))
        .unwrap();
    assert_eq!(pending(&engine, &bob), ["b"]);
    // Alice's capture was given to Alice: Bob never read that revision.
    let alices = engine.capture_for(&alice).unwrap();
    let refused = engine.review(&bob, keep("b", alices.revision)).unwrap_err();
    assert!(refused.to_string().contains("captured"), "{refused}");
    assert_eq!(pending(&engine, &bob), ["b"]);
    // Bob's own capture of the same revision accumulates beside Alice's.
    let bobs = engine.capture_for(&bob).unwrap();
    assert_eq!(bobs.revision, alices.revision);
    assert!(
        !engine
            .review(&bob, keep("b", bobs.revision))
            .unwrap()
            .pending()
    );
    assert!(
        !engine
            .review(&alice, keep("a", alices.revision))
            .unwrap()
            .pending()
    );
}

#[test]
fn a_host_internal_capture_authorizes_an_offer_but_no_review() {
    let (_dir, engine, alice, bob) = fixture(PAIR);
    engine.register(&bob, scope("b", &["b.rs"])).unwrap();
    let base = engine.capture_for(&alice).unwrap();
    engine
        .apply(&alice, edit("peer", &base, "a.rs", "fn a() { 2 }\n"))
        .unwrap();
    // The host read Bob's workspace without giving the read to Bob.
    let host = engine.host_capture(&bob).unwrap();
    assert_eq!(host.revision, base.revision + 1);
    let refused = engine.review(&bob, keep("b", host.revision)).unwrap_err();
    assert!(refused.to_string().contains("captured"), "{refused}");
    assert_eq!(pending(&engine, &bob), ["b"]);
    // Any recorded capture still names an offerable revision.
    let offered = engine
        .offer(
            &alice,
            Offer {
                id: "host".into(),
                task: "task a".into(),
                revision: host.revision,
                scope: Vec::new(),
                text: "the revision the host checked".into(),
                supersedes: None,
                reviews: Vec::new(),
            },
        )
        .unwrap();
    assert_eq!(offered.capture, host);
}

/// Bob's scope `b` renewed by Alice's edit of a.rs, and Bob's own read of that revision.
fn renewed(engine: &Engine, alice: &Client, bob: &Client) -> Capture {
    engine.register(bob, scope("b", &["b.rs"])).unwrap();
    let base = engine.capture_for(alice).unwrap();
    engine
        .apply(alice, edit("peer", &base, "a.rs", "fn a() { 2 }\n"))
        .unwrap();
    assert_eq!(pending(engine, bob), ["b"]);
    engine.capture_for(bob).unwrap()
}

#[test]
fn an_inline_keep_lets_an_edit_apply_that_would_be_unreviewed() {
    let (_dir, engine, alice, bob) = fixture(PAIR);
    let current = renewed(&engine, &alice, &bob);
    let mut request = edit("inline", &current, "b.rs", "fn b() { 2 }\n");
    request.reviews = vec![keep("b", current.revision)];
    assert!(matches!(
        engine.apply(&bob, request.clone()).unwrap(),
        Outcome::Applied { .. }
    ));
    assert!(pending(&engine, &bob).is_empty());
    // A replay returns the recorded outcome without reviewing again.
    assert!(matches!(
        engine.apply(&bob, request).unwrap(),
        Outcome::Applied { .. }
    ));
    // Alice sees the review once, as a separate review call would show it.
    let reviewed = engine.events(&alice, 0).unwrap();
    let reviews = reviewed
        .iter()
        .filter(|e| matches!(&e.body, Body::Reviewed { agent: 1, review } if review.scope == "b"))
        .count();
    assert_eq!(reviews, 1, "{reviewed:?}");
}

#[test]
fn an_invalid_inline_review_leaves_no_review_and_no_edit() {
    let (_dir, engine, alice, bob) = fixture(PAIR);
    let current = renewed(&engine, &alice, &bob);
    let before = engine.events(&alice, 0).unwrap().len();
    let mut request = edit("invalid", &current, "b.rs", "fn b() { 2 }\n");
    // The first review is valid; the second names a revision Bob was never given.
    request.reviews = vec![keep("b", current.revision), keep("b", current.revision + 1)];
    let refused = engine.apply(&bob, request).unwrap_err();
    assert!(refused.to_string().contains("captured"), "{refused}");
    assert_eq!(pending(&engine, &bob), ["b"]);
    assert!(engine.request(&bob, "invalid").unwrap().is_none());
    assert_eq!(engine.capture_for(&bob).unwrap().revision, current.revision);
    assert_eq!(engine.events(&alice, 0).unwrap().len(), before);
}

#[test]
fn a_stale_edit_keeps_its_inline_reviews() {
    let (_dir, engine, alice, bob) = fixture(PAIR);
    let current = renewed(&engine, &alice, &bob);
    // Bob also relies on a.rs as it was before Alice's edit.
    let mut request = edit("stale", &current, "b.rs", "fn b() { 2 }\n");
    request.expected.insert("a.rs".into(), 0);
    request.reviews = vec![keep("b", current.revision)];
    assert!(matches!(
        engine.apply(&bob, request).unwrap(),
        Outcome::Stale { .. }
    ));
    assert!(pending(&engine, &bob).is_empty());
}

#[test]
fn an_offer_with_an_inline_review_clears_the_obligation_and_offers() {
    let (_dir, engine, alice, bob) = fixture(PAIR);
    let current = renewed(&engine, &alice, &bob);
    let offer = Offer {
        id: "inline".into(),
        task: "task b".into(),
        revision: current.revision,
        scope: vec!["b".into()],
        text: "nothing of mine changed".into(),
        supersedes: None,
        reviews: Vec::new(),
    };
    let refused = engine.offer(&bob, offer.clone()).unwrap_err();
    assert!(refused.to_string().contains("unreviewed"), "{refused}");
    let offered = engine
        .offer(
            &bob,
            Offer {
                reviews: vec![keep("b", current.revision)],
                ..offer
            },
        )
        .unwrap();
    assert_eq!(offered.state, Availability::Available);
    assert!(pending(&engine, &bob).is_empty());
    // A replayed offer reviews nothing again.
    let before = engine.events(&alice, 0).unwrap().len();
    assert_eq!(engine.offer(&bob, offered.offer.clone()).unwrap(), offered);
    assert_eq!(engine.events(&alice, 0).unwrap().len(), before);
}

#[test]
fn replay_restores_deferred_context_and_obligations_without_duplicates_after_restart() {
    let (dir, engine, alice, bob) = fixture(PAIR);
    engine.register(&alice, scope("a", &["a.rs"])).unwrap();
    let base = engine.capture().unwrap();
    engine
        .apply(&bob, edit("peer", &base, "b.rs", "changed\n"))
        .unwrap();
    let events = engine.events(&alice, 0).unwrap();
    engine
        .handle(
            &alice,
            Some(events[0].seq),
            &note(events[0].seq, "later"),
            &[],
        )
        .unwrap();
    drop(engine);
    let engine = open(dir.path(), PAIR).unwrap();
    let alice = engine.authenticate(0, &engine.credentials()[0]).unwrap();
    let restored = engine.pending(&alice).unwrap();
    assert_eq!(restored.handled, events[0].seq);
    assert_eq!(restored.deferred.len(), 1);
    assert_eq!(restored.deferred[0].0, events[0], "stable identity");
    assert_eq!(restored.unhandled, events[1..]);
    assert_eq!(restored.obligations.len(), 1);
    // Redelivery after a crash before the cursor save is duplicate-safe.
    for _ in 0..2 {
        engine
            .handle(
                &alice,
                Some(events[1].seq),
                &note(events[0].seq, "again"),
                &[],
            )
            .unwrap();
    }
    let again = engine.pending(&alice).unwrap();
    assert_eq!(again.deferred.len(), 1);
    assert_eq!(again.deferred[0].1, "later");
    assert!(again.unhandled.is_empty());
    assert_eq!(again.obligations.len(), 1);
    assert_eq!(engine.events(&alice, 0).unwrap(), events);
}

fn plan(text: &str) -> Plan {
    Plan {
        task: "consumer".into(),
        scope: vec!["b.rs".into()],
        work: Work::None,
        text: text.into(),
        reply_to: None,
    }
}
/// The seqs of `count` plans from `sender`, in its peer's stream.
fn plans(engine: &Engine, sender: &Client, count: usize) -> Vec<u64> {
    (0..count)
        .map(|n| engine.post(sender, plan(&format!("plan {n}"))).unwrap().seq)
        .collect()
}
fn seqs(events: &[Event]) -> Vec<u64> {
    events.iter().map(|e| e.seq).collect()
}
fn note(seq: u64, text: &str) -> BTreeMap<u64, String> {
    BTreeMap::from([(seq, text.into())])
}

#[test]
fn one_handle_call_processes_every_event_through_its_seq() {
    let (_dir, engine, alice, bob) = fixture(PAIR);
    let posted = plans(&engine, &bob, 3);
    engine
        .handle(&alice, Some(posted[1]), &BTreeMap::new(), &[])
        .unwrap();
    let pending = engine.pending(&alice).unwrap();
    assert_eq!(pending.handled, posted[1]);
    assert_eq!(seqs(&pending.unhandled), [posted[2]]);
    assert!(pending.deferred.is_empty());
}

#[test]
fn deferrals_survive_reopen_until_processed_clears_them() {
    let (dir, engine, alice, bob) = fixture(PAIR);
    let posted = plans(&engine, &bob, 3);
    engine
        .handle(
            &alice,
            Some(posted[2]),
            &note(posted[0], "after my edit"),
            &[],
        )
        .unwrap();
    // A deferral may name an event processed earlier.
    engine
        .handle(&alice, None, &note(posted[1], "after my edit"), &[])
        .unwrap();
    drop(engine);
    let (engine, alice, _) = reopen(dir.path(), PAIR);
    let restored = engine.pending(&alice).unwrap();
    let events = engine.events(&alice, 0).unwrap();
    assert_eq!(restored.handled, posted[2]);
    assert!(restored.unhandled.is_empty());
    assert_eq!(
        restored.deferred,
        [
            (events[0].clone(), "after my edit".into()),
            (events[1].clone(), "after my edit".into())
        ]
    );
    engine
        .handle(&alice, None, &BTreeMap::new(), &[posted[0]])
        .unwrap();
    assert_eq!(
        engine.pending(&alice).unwrap().deferred,
        [(events[1].clone(), "after my edit".into())]
    );
}

#[test]
fn repeated_handling_changes_nothing_and_may_end_at_an_own_post() {
    let (_dir, engine, alice, bob) = fixture(PAIR);
    let theirs = plans(&engine, &bob, 1)[0];
    // Alice's own post goes only to Bob, so it is not in her stream.
    let own = engine.post(&alice, plan("mine")).unwrap().seq;
    engine
        .handle(&alice, Some(own), &note(theirs, "later"), &[])
        .unwrap();
    let once = engine.pending(&alice).unwrap();
    assert_eq!(once.handled, own);
    assert!(once.unhandled.is_empty());
    engine
        .handle(&alice, Some(own), &note(theirs, "later"), &[])
        .unwrap();
    engine
        .handle(&alice, Some(theirs), &note(theirs, "changed"), &[])
        .unwrap();
    assert_eq!(engine.pending(&alice).unwrap(), once);
}

#[test]
fn refused_handling_changes_nothing() {
    let (_dir, engine, alice, bob) = fixture(PAIR);
    let posted = plans(&engine, &bob, 2);
    engine
        .handle(&alice, Some(posted[0]), &BTreeMap::new(), &[])
        .unwrap();
    let own = engine.post(&alice, plan("mine")).unwrap().seq;
    let before = engine.pending(&alice).unwrap();
    for (through, deferred, processed, why) in [
        (
            Some(posted[1]),
            note(posted[1], "later"),
            vec![posted[1]],
            "contradictory",
        ),
        (
            Some(own + 1),
            BTreeMap::new(),
            vec![],
            "beyond the newest event",
        ),
        (
            None,
            note(posted[1], "later"),
            vec![],
            "deferral beyond the new cursor",
        ),
        (
            Some(own),
            note(own, "later"),
            vec![],
            "deferral outside the stream",
        ),
    ] {
        assert!(
            engine
                .handle(&alice, through, &deferred, &processed)
                .is_err(),
            "{why}"
        );
        assert_eq!(engine.pending(&alice).unwrap(), before, "{why}");
    }
}

#[test]
fn waits_catch_up_on_missed_wakeups_and_report_explicit_outcomes() {
    let (_dir, engine, alice, bob) = fixture(PAIR);
    // Committed before the wait began: catch-up, not a lost wakeup.
    let early = engine.post(&bob, plan("early")).unwrap();
    assert!(
        engine
            .wait(&bob, Condition::Message { from: 1, after: 0 }, None, None)
            .is_err()
    );
    let from_bob = |after| Condition::Message { from: 1, after };
    assert_eq!(
        engine
            .wait(&alice, from_bob(0), Some(Duration::ZERO), None)
            .unwrap(),
        WaitOutcome::Met(early.clone())
    );
    std::thread::scope(|scope| {
        let waiter = scope.spawn(|| engine.wait(&alice, from_bob(early.seq), None, None));
        std::thread::sleep(Duration::from_millis(50));
        engine.post(&bob, plan("late")).unwrap();
        assert!(matches!(
            waiter.join().unwrap().unwrap(),
            WaitOutcome::Met(_)
        ));
    });
    let after = engine.events(&alice, 0).unwrap().last().unwrap().seq;
    assert_eq!(
        engine
            .wait(
                &alice,
                from_bob(after),
                Some(Duration::from_millis(20)),
                None
            )
            .unwrap(),
        WaitOutcome::TimedOut
    );
    let cancel = engine.cancel_token();
    std::thread::scope(|scope| {
        let waiter = scope.spawn(|| engine.wait(&alice, from_bob(after), None, Some(&cancel)));
        std::thread::sleep(Duration::from_millis(50));
        cancel.cancel();
        assert_eq!(waiter.join().unwrap().unwrap(), WaitOutcome::Cancelled);
    });
    std::thread::scope(|scope| {
        let waiter = scope.spawn(|| engine.wait(&alice, from_bob(after), None, None));
        std::thread::sleep(Duration::from_millis(50));
        engine.disconnect(&bob).unwrap();
        assert_eq!(
            waiter.join().unwrap().unwrap(),
            WaitOutcome::Disconnected { agent: 1 }
        );
    });
    // Retry after reconnection is explicit and works normally.
    let bob = engine.authenticate(1, &engine.credentials()[1]).unwrap();
    engine.post(&bob, plan("back")).unwrap();
    assert!(matches!(
        engine.wait(&alice, from_bob(after), None, None).unwrap(),
        WaitOutcome::Met(_)
    ));
}

#[test]
fn checkpoint_offers_survive_live_editing_and_end_exact_waits_without_rebinding() {
    let (_dir, engine, alice, bob) = fixture(PAIR);
    engine.register(&bob, scope("b", &["b.rs"])).unwrap();
    let base = engine.capture().unwrap();
    let offer = |id: &str, revision: u64, supersedes: Option<&str>| Offer {
        id: id.into(),
        task: "producer".into(),
        revision,
        scope: vec!["b.rs".into()],
        text: format!("offer {id}"),
        supersedes: supersedes.map(String::from),
        reviews: Vec::new(),
    };
    let c1 = engine
        .offer(&bob, offer("c1", base.revision, None))
        .unwrap();
    engine
        .apply(&bob, edit("draft", &base, "b.rs", "later live draft\n"))
        .unwrap();
    assert_eq!(
        engine.checkpoint(&c1.id).unwrap().unwrap(),
        c1,
        "live edits leave the offer intact"
    );
    // A reply binds the original message and its exact work.
    let offered = engine
        .events(&alice, 0)
        .unwrap()
        .into_iter()
        .find(|e| matches!(&e.body, Body::Message(m) if m.kind == Kind::CheckpointOffer))
        .unwrap();
    let reply = |work: Work| Plan {
        task: "consumer".into(),
        scope: vec!["a.rs".into()],
        work: work.clone(),
        text: "reviewed this checkpoint".into(),
        reply_to: Some(Reply {
            event: offered.seq,
            work,
        }),
    };
    assert!(engine.post(&alice, reply(Work::Revision(1))).is_err());
    engine
        .post(&alice, reply(Work::Checkpoint(c1.id.clone())))
        .unwrap();
    // A peer edit renews Bob's obligation; offers covering it are gated.
    let current = engine.capture().unwrap();
    engine
        .apply(&alice, edit("peer", &current, "a.rs", "fn a() { 2 }\n"))
        .unwrap();
    let current = engine.capture().unwrap();
    assert!(
        engine
            .offer(&bob, offer("c2", current.revision, Some("c1")))
            .is_err()
    );
    assert!(
        engine
            .offer(&bob, offer("older", base.revision, None))
            .is_err(),
        "pending review blocks even an older offer"
    );
    reread(&engine, &bob, "b");
    let wait = Condition::Checkpoint { id: c1.id.clone() };
    std::thread::scope(|scope| {
        let waiter = scope.spawn(|| engine.wait(&alice, wait.clone(), None, None));
        std::thread::sleep(Duration::from_millis(50));
        engine
            .offer(&bob, offer("c2", current.revision, Some("c1")))
            .unwrap();
        assert_eq!(
            waiter.join().unwrap().unwrap(),
            WaitOutcome::Superseded {
                checkpoint: c1.id.clone(),
                replacement: "1/c2".into()
            }
        );
    });
    assert_eq!(
        engine.checkpoint(&c1.id).unwrap().unwrap().capture,
        base,
        "history retained"
    );
    engine.withdraw(&bob, "c2").unwrap();
    assert_eq!(
        engine
            .wait(
                &alice,
                Condition::Checkpoint { id: "1/c2".into() },
                None,
                None
            )
            .unwrap(),
        WaitOutcome::Withdrawn {
            checkpoint: "1/c2".into()
        }
    );
    let c3 = engine
        .offer(&bob, offer("c3", current.revision, None))
        .unwrap();
    engine.disconnect(&bob).unwrap();
    assert_eq!(
        engine
            .wait(&alice, Condition::Checkpoint { id: c3.id }, None, None)
            .unwrap(),
        WaitOutcome::Disconnected { agent: 1 }
    );
}
